// Finance — Chapter 4: helpers and data shared by ch04.js and ch04-b.js (plain functions, no runtime access).
//
// DATA. Everything below the "data" banner is real: monthly returns downloaded in October 2026 from Kenneth R.
// French's Data Library (Tuck School, Dartmouth: mba.tuck.dartmouth.edu/pages/faculty/ken.french/data_library.html),
// built from CRSP (database vintage 202608, so the last months are recent and may be revised). Returns are stored in
// percent × 100 as integers; `series(name)` below decodes them to decimals (0.0123 = 1.23% a month).
//   D_FF   Fama–French factors Mkt−RF, SMB, HML and the one-month T-bill rate RF, 1963-07 … 2026-08
//   D_P25  the 25 portfolios formed on size and book-to-market (value-weighted)
//   D_BETA the ten portfolios formed on past beta (value-weighted; beta from 60 months, Scholes–Williams)
//   D_IND  the ten industry portfolios (value-weighted)
//   D_MOM  the momentum factor, 1927-01 …, and D_PRI the ten portfolios formed on prior return (months −12 to −2)
export { clamp, pct, fx, sg, bp, money, usd, dl, pctTicks } from './ch02.shared.js';
import { fx, pct } from './ch02.shared.js';

const decode = (s) => Float64Array.from(s.split(' '), (x) => Number(x) / 10000);
export const decodeAll = (rows) => rows.map(decode);

/** Month index (0 = July 1963) → [year, month]; ym0 for the series of 1927-01. */
export const ymOf = (i, y0 = 1963, m0 = 7) => { const k = m0 - 1 + i; return [y0 + Math.floor(k / 12), (k % 12) + 1]; };
export const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
export const monthLabel = (i, y0 = 1963, m0 = 7) => { const [y, m] = ymOf(i, y0, m0); return `${MON[m - 1]} ${y}`; };
/** Index in a series that starts at (y0, m0) of the month (y, m). */
export const idxOf = (y, m = 1, y0 = 1963, m0 = 7) => (y - y0) * 12 + (m - m0);

// ---------------------------------------------------------------- small statistics
export const mean = (a, i0 = 0, i1 = a.length) => { let s = 0; for (let i = i0; i < i1; i++) s += a[i]; return s / (i1 - i0); };
export const sdev = (a, i0 = 0, i1 = a.length) => { const m = mean(a, i0, i1); let s = 0; for (let i = i0; i < i1; i++) s += (a[i] - m) ** 2; return Math.sqrt(s / (i1 - i0 - 1)); };
/** Solve A x = b by Gaussian elimination with partial pivoting (A: array of rows); null if singular. */
export function solveLin(A, b) {
  const n = A.length, M = A.map((r, i) => [...r, b[i]]);
  for (let c = 0; c < n; c++) {
    let p = c; for (let r = c + 1; r < n; r++) if (Math.abs(M[r][c]) > Math.abs(M[p][c])) p = r;
    if (Math.abs(M[p][c]) < 1e-14) return null;
    [M[c], M[p]] = [M[p], M[c]];
    for (let r = c + 1; r < n; r++) { const f = M[r][c] / M[c][c]; for (let k = c; k <= n; k++) M[r][k] -= f * M[c][k]; }
  }
  const x = new Array(n).fill(0);
  for (let r = n - 1; r >= 0; r--) { let s = M[r][n]; for (let k = r + 1; k < n; k++) s -= M[r][k] * x[k]; x[r] = s / M[r][r]; }
  return x;
}
/** Inverse of a square matrix (Gauss–Jordan); null if singular. */
export function invert(A) {
  const n = A.length, M = A.map((r, i) => [...r, ...Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))]);
  for (let c = 0; c < n; c++) {
    let p = c; for (let r = c + 1; r < n; r++) if (Math.abs(M[r][c]) > Math.abs(M[p][c])) p = r;
    if (Math.abs(M[p][c]) < 1e-13) return null;
    [M[c], M[p]] = [M[p], M[c]];
    const d = M[c][c]; for (let k = 0; k < 2 * n; k++) M[c][k] /= d;
    for (let r = 0; r < n; r++) if (r !== c) { const f = M[r][c]; if (f) for (let k = 0; k < 2 * n; k++) M[r][k] -= f * M[c][k]; }
  }
  return M.map((r) => r.slice(n));
}
export const matVec = (A, x) => A.map((r) => r.reduce((s, a, j) => s + a * x[j], 0));
export const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);

/**
 * Least squares of y on an intercept and the regressors Xs (arrays), over observations i0 … i1−1.
 * → { b: [alpha, beta1, …], se, t, r2, s (residual sd), n, resid }.
 */
export function ols(y, Xs, i0 = 0, i1 = y.length) {
  const n = i1 - i0, k = Xs.length + 1;
  const col = (j, i) => (j === 0 ? 1 : Xs[j - 1][i]);
  const A = Array.from({ length: k }, () => new Array(k).fill(0)), r = new Array(k).fill(0);
  for (let i = i0; i < i1; i++) for (let a = 0; a < k; a++) { const xa = col(a, i); r[a] += xa * y[i]; for (let b = a; b < k; b++) A[a][b] += xa * col(b, i); }
  for (let a = 0; a < k; a++) for (let b = 0; b < a; b++) A[a][b] = A[b][a];
  const Ai = invert(A);
  if (!Ai) return null;
  const b = matVec(Ai, r);
  let sse = 0, sst = 0, my = 0; for (let i = i0; i < i1; i++) my += y[i]; my /= n;
  const resid = new Float64Array(n);
  for (let i = i0; i < i1; i++) { let f = 0; for (let j = 0; j < k; j++) f += b[j] * col(j, i); resid[i - i0] = y[i] - f; sse += resid[i - i0] ** 2; sst += (y[i] - my) ** 2; }
  const s2 = sse / (n - k), se = Ai.map((row, j) => Math.sqrt(s2 * row[j]));
  return { b, se, t: b.map((x, j) => x / se[j]), r2: 1 - sse / sst, s: Math.sqrt(s2), n, resid };
}
/** Excess-return series: a[i] − rf[i]. */
export const excess = (a, rf) => { const o = new Float64Array(a.length); for (let i = 0; i < a.length; i++) o[i] = a[i] - rf[i]; return o; };
/** Annualised percent text of a monthly decimal mean: ann(0.0071) → "8.5%". */
export const ann = (m, d = 1) => pct(12 * m, d);

// ---------------------------------------------------------------- mean–variance helpers (unconstrained weights)
/** Constants of the frontier of assets with means mu and covariance S: a = 1'S⁻¹1, b = 1'S⁻¹μ, c = μ'S⁻¹μ. */
export function frontierConsts(mu, S) {
  const Si = invert(S); if (!Si) return null;
  const one = mu.map(() => 1), Sm = matVec(Si, mu), S1 = matVec(Si, one);
  return { Si, a: dot(one, S1), b: dot(one, Sm), c: dot(mu, Sm), Sm, S1 };
}
/** Standard deviation of the frontier portfolio of mean m. */
export const frontierSd = (F, m) => Math.sqrt(Math.max(0, (F.a * m * m - 2 * F.b * m + F.c) / (F.a * F.c - F.b * F.b)));
/** Weights of the minimum-variance portfolio with mean m (weights sum to 1, shorting allowed). */
export function frontierWeights(F, m) {
  const D = F.a * F.c - F.b * F.b, l = (F.c - F.b * m) / D, g = (F.a * m - F.b) / D;
  return F.S1.map((x, i) => l * x + g * F.Sm[i]);
}
/** Tangency portfolio for riskless rate rf: weights ∝ S⁻¹(μ − rf); null if the denominator is not positive. */
export function tangency(mu, S, rf) {
  const z = solveLin(S, mu.map((m) => m - rf)); if (!z) return null;
  const t = z.reduce((a, b) => a + b, 0); if (!(Math.abs(t) > 1e-12)) return null;
  return z.map((x) => x / t);
}
export const covRho = (sd, R) => R.map((row, i) => row.map((r, j) => r * sd[i] * sd[j]));
export const quad = (w, S) => dot(w, matVec(S, w));

/** Deterministic seeded pseudo-random generator (mulberry32) with a normal() method, usable outside the runtime. */
export function rng(seed) {
  let s = seed >>> 0;
  const r = () => { s = (s + 0x6d2b79f5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  r.normal = () => { let u = 0; while (u === 0) u = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r()); };
  return r;
}
export const signText = (x, d = 1) => (x < 0 ? '−' : '+') + Math.abs(x).toFixed(d);

